/* CommerceForge Dev Docs — Global Styles */
:root {
  --bg-primary: #0d1117;
  --bg-secondary: #161b22;
  --bg-tertiary: #1c2128;
  --bg-card: #161b22;
  --border-color: #30363d;
  --border-subtle: #21262d;
  --text-primary: #e6edf3;
  --text-secondary: #8b949e;
  --text-muted: #6e7681;
  --accent: #00e5a0;
  --accent-hover: #00cc8e;
  --accent-dim: rgba(0, 229, 160, 0.1);
  --accent-blue: #475F91;
  --accent-cyan: #00d4ff;
  --accent-purple: #a78bfa;
  --accent-orange: #f0883e;
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif;
  --font-mono: 'JetBrains Mono', 'Fira Code', 'Cascadia Code', 'Consolas', monospace;
  --radius: 8px;
  --radius-lg: 12px;
  --shadow-card: 0 1px 3px rgba(0,0,0,0.3), 0 0 0 1px var(--border-color);
  --shadow-glow: 0 0 20px rgba(0, 229, 160, 0.08);
  --max-width: 1280px;
  --sidebar-width: 260px;
  --transition: 0.2s ease;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-sans);
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

a { color: var(--accent); text-decoration: none; transition: color var(--transition); }
a:hover { color: var(--accent-hover); }

img { max-width: 100%; display: block; }

code, pre { font-family: var(--font-mono); }

/* Top Navigation */
.topnav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(13, 17, 23, 0.85);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--border-color);
}

.topnav-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 24px;
  height: 60px;
}

.topnav-logo {
  font-weight: 700;
  font-size: 1.05rem;
  color: var(--text-primary);
  display: flex;
  align-items: center;
  gap: 8px;
  white-space: nowrap;
}

.topnav-logo svg { flex-shrink: 0; }

.topnav-links {
  display: flex;
  align-items: center;
  gap: 4px;
  list-style: none;
}

.topnav-links a {
  color: var(--text-secondary);
  font-size: 0.875rem;
  font-weight: 500;
  padding: 6px 14px;
  border-radius: 6px;
  transition: all var(--transition);
}

.topnav-links a:hover,
.topnav-links a.active {
  color: var(--text-primary);
  background: var(--bg-tertiary);
}

.topnav-right {
  display: flex;
  align-items: center;
  gap: 12px;
}

.search-btn {
  display: flex;
  align-items: center;
  gap: 6px;
  background: var(--bg-tertiary);
  border: 1px solid var(--border-color);
  color: var(--text-muted);
  padding: 6px 12px;
  border-radius: 6px;
  font-size: 0.8125rem;
  cursor: pointer;
  transition: all var(--transition);
}

.search-btn:hover { border-color: var(--text-muted); color: var(--text-secondary); }

.search-btn kbd {
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: 3px;
  padding: 1px 5px;
  font-size: 0.7rem;
  font-family: var(--font-sans);
}

.login-link {
  color: var(--text-secondary) !important;
  font-size: 0.875rem;
  font-weight: 500;
}

.hamburger {
  display: none;
  background: none;
  border: none;
  color: var(--text-primary);
  cursor: pointer;
  padding: 4px;
}

/* Hero */
.hero {
  padding: 80px 24px 64px;
  text-align: center;
  max-width: 860px;
  margin: 0 auto;
}

.hero h1 {
  font-size: 2.75rem;
  font-weight: 800;
  line-height: 1.15;
  letter-spacing: -0.03em;
  margin-bottom: 20px;
  background: linear-gradient(135deg, var(--text-primary) 0%, var(--accent) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.hero p {
  font-size: 1.125rem;
  color: var(--text-secondary);
  line-height: 1.7;
  max-width: 680px;
  margin: 0 auto 32px;
}

.hero-ctas {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-weight: 600;
  font-size: 0.875rem;
  padding: 10px 20px;
  border-radius: 6px;
  border: none;
  cursor: pointer;
  transition: all var(--transition);
  text-decoration: none;
}

.btn-primary {
  background: var(--accent);
  color: #0d1117;
}

.btn-primary:hover { background: var(--accent-hover); color: #0d1117; transform: translateY(-1px); }

.btn-secondary {
  background: transparent;
  color: var(--text-primary);
  border: 1px solid var(--border-color);
}

.btn-secondary:hover { border-color: var(--text-secondary); background: var(--bg-tertiary); color: var(--text-primary); }

.btn-ghost {
  background: transparent;
  color: var(--accent);
  padding: 10px 4px;
}

.btn-ghost:hover { color: var(--accent-hover); }

/* Section */
.section {
  padding: 64px 24px;
  max-width: var(--max-width);
  margin: 0 auto;
}

.section-header {
  margin-bottom: 40px;
}

.section-header h2 {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: 12px;
}

.section-header p {
  font-size: 1rem;
  color: var(--text-secondary);
  max-width: 600px;
}

.section-label {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--accent);
  margin-bottom: 8px;
}

/* Card Grid */
.card-grid {
  display: grid;
  gap: 16px;
}

.card-grid-3 { grid-template-columns: repeat(3, 1fr); }
.card-grid-2 { grid-template-columns: repeat(2, 1fr); }

.card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 24px;
  transition: all var(--transition);
  position: relative;
  overflow: hidden;
}

.card:hover {
  border-color: var(--accent);
  box-shadow: var(--shadow-glow);
  transform: translateY(-2px);
}

.card-icon {
  width: 40px;
  height: 40px;
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 16px;
  font-size: 1.25rem;
}

.card-icon-green { background: rgba(0, 229, 160, 0.12); color: var(--accent); }
.card-icon-blue { background: rgba(0, 212, 255, 0.12); color: var(--accent-cyan); }
.card-icon-purple { background: rgba(167, 139, 250, 0.12); color: var(--accent-purple); }
.card-icon-orange { background: rgba(240, 136, 62, 0.12); color: var(--accent-orange); }

.card h3 {
  font-size: 1.05rem;
  font-weight: 600;
  margin-bottom: 8px;
}

.card p {
  font-size: 0.875rem;
  color: var(--text-secondary);
  line-height: 1.6;
  margin-bottom: 16px;
}

.card-link {
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--accent);
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.card-link:hover { gap: 8px; }

/* Product Cards */
.product-card {
  padding: 32px;
  display: flex;
  flex-direction: column;
}

.product-card .card-link { margin-top: auto; }

/* CLI Setup */
.cli-section {
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  overflow: hidden;
}

.cli-header {
  padding: 32px 32px 24px;
}

.cli-header h2 {
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 8px;
}

.cli-header p {
  font-size: 0.9375rem;
  color: var(--text-secondary);
  max-width: 600px;
}

/* Accordion */
.accordion-item {
  border-top: 1px solid var(--border-color);
}

.accordion-trigger {
  width: 100%;
  background: none;
  border: none;
  color: var(--text-primary);
  font-size: 0.9375rem;
  font-weight: 600;
  padding: 16px 32px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  cursor: pointer;
  transition: background var(--transition);
  font-family: var(--font-sans);
}

.accordion-trigger:hover { background: var(--bg-tertiary); }

.accordion-trigger svg {
  transition: transform var(--transition);
  flex-shrink: 0;
  color: var(--text-muted);
}

.accordion-trigger[aria-expanded="true"] svg { transform: rotate(180deg); }
.accordion-trigger[aria-expanded="true"] { color: var(--accent); }

.accordion-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s ease;
}

.accordion-content-inner {
  padding: 0 32px 24px;
}

.accordion-content.open {
  max-height: 600px;
}

.cli-steps {
  list-style: none;
  counter-reset: step;
  margin-bottom: 20px;
}

.cli-steps li {
  counter-increment: step;
  padding: 8px 0 8px 36px;
  position: relative;
  font-size: 0.875rem;
  color: var(--text-secondary);
}

.cli-steps li::before {
  content: counter(step);
  position: absolute;
  left: 0;
  width: 24px;
  height: 24px;
  background: var(--accent-dim);
  color: var(--accent);
  font-size: 0.75rem;
  font-weight: 700;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* Code Block */
.code-block {
  background: #010409;
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  overflow: hidden;
}

.code-tabs {
  display: flex;
  border-bottom: 1px solid var(--border-color);
}

.code-tab {
  background: none;
  border: none;
  color: var(--text-muted);
  font-size: 0.8125rem;
  font-weight: 500;
  padding: 8px 16px;
  cursor: pointer;
  border-bottom: 2px solid transparent;
  font-family: var(--font-sans);
  transition: all var(--transition);
}

.code-tab:hover { color: var(--text-secondary); }

.code-tab.active {
  color: var(--accent);
  border-bottom-color: var(--accent);
}

.code-content {
  padding: 16px;
  font-family: var(--font-mono);
  font-size: 0.8125rem;
  line-height: 1.7;
  color: var(--text-primary);
  overflow-x: auto;
}

.code-content .prompt { color: var(--accent); user-select: none; }
.code-content .cmd { color: var(--text-primary); }
.code-content .flag { color: var(--accent-cyan); }
.code-content .pkg { color: var(--accent-orange); }

pre.code-line {
  white-space: pre;
  margin: 0;
  padding: 2px 0;
}

/* Launch Section */
.launch-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}

.launch-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 32px;
  transition: all var(--transition);
}

.launch-card:hover {
  border-color: var(--accent);
  box-shadow: var(--shadow-glow);
}

.launch-card h3 {
  font-size: 1.125rem;
  font-weight: 700;
  margin-bottom: 10px;
}

.launch-card p {
  font-size: 0.875rem;
  color: var(--text-secondary);
  line-height: 1.6;
  margin-bottom: 16px;
}

/* Community Section */
.community-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
}

.community-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 20px;
  transition: all var(--transition);
  text-decoration: none;
  display: block;
}

.community-card:hover {
  border-color: var(--accent);
  transform: translateY(-2px);
}

.community-card h4 {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-primary);
  margin-bottom: 6px;
  display: flex;
  align-items: center;
  gap: 6px;
}

.community-card p {
  font-size: 0.8125rem;
  color: var(--text-muted);
  line-height: 1.5;
}

/* Footer */
.footer {
  border-top: 1px solid var(--border-color);
  padding: 48px 24px 32px;
  margin-top: 64px;
}

.footer-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 32px;
}

.footer-col h4 {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-muted);
  margin-bottom: 16px;
}

.footer-col a {
  display: block;
  font-size: 0.8125rem;
  color: var(--text-secondary);
  padding: 3px 0;
}

.footer-col a:hover { color: var(--text-primary); }

.footer-bottom {
  max-width: var(--max-width);
  margin: 32px auto 0;
  padding-top: 24px;
  border-top: 1px solid var(--border-color);
  font-size: 0.75rem;
  color: var(--text-muted);
}

/* Docs Layout with Sidebar */
.docs-layout {
  display: flex;
  min-height: calc(100vh - 60px);
}

.sidebar {
  width: var(--sidebar-width);
  background: var(--bg-secondary);
  border-right: 1px solid var(--border-color);
  padding: 24px 0;
  position: sticky;
  top: 60px;
  height: calc(100vh - 60px);
  overflow-y: auto;
  transition: width 0.3s ease, padding 0.3s ease, opacity 0.3s ease;
  flex-shrink: 0;
}

.sidebar.collapsed {
  width: 0;
  padding: 0;
  overflow: hidden;
  opacity: 0;
}

.sidebar-toggle {
  position: fixed;
  left: var(--sidebar-width);
  top: 72px;
  z-index: 50;
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  color: var(--text-muted);
  width: 28px;
  height: 28px;
  border-radius: 0 6px 6px 0;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: left 0.3s ease, background var(--transition);
}

.sidebar-toggle:hover { background: var(--bg-tertiary); color: var(--text-primary); }

.sidebar-toggle.collapsed-btn {
  left: 0;
  border-radius: 0 6px 6px 0;
}

.sidebar-section {
  padding: 0 16px;
  margin-bottom: 24px;
}

.sidebar-section h3 {
  font-size: 0.6875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-muted);
  padding: 0 8px;
  margin-bottom: 4px;
}

.sidebar-link {
  display: block;
  font-size: 0.8125rem;
  color: var(--text-secondary);
  padding: 6px 8px;
  border-radius: 4px;
  transition: all var(--transition);
}

.sidebar-link:hover { color: var(--text-primary); background: var(--bg-tertiary); }
.sidebar-link.active { color: var(--accent); background: var(--accent-dim); }

.docs-main {
  flex: 1;
  min-width: 0;
  padding: 48px 48px 80px;
  max-width: 900px;
}

.docs-main h1 {
  font-size: 2.25rem;
  font-weight: 800;
  letter-spacing: -0.03em;
  margin-bottom: 12px;
}

.docs-main > p {
  font-size: 1.0625rem;
  color: var(--text-secondary);
  line-height: 1.7;
  margin-bottom: 40px;
}

.docs-section { margin-bottom: 56px; }

.docs-section h2 {
  font-size: 1.375rem;
  font-weight: 700;
  margin-bottom: 8px;
  letter-spacing: -0.01em;
}

.docs-section > p {
  font-size: 0.9375rem;
  color: var(--text-secondary);
  margin-bottom: 24px;
  line-height: 1.6;
}

.mini-card {
  background: var(--bg-tertiary);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 20px;
  transition: all var(--transition);
}

.mini-card:hover {
  border-color: var(--text-muted);
  transform: translateY(-1px);
}

.mini-card h4 {
  font-size: 0.9375rem;
  font-weight: 600;
  margin-bottom: 6px;
}

.mini-card p {
  font-size: 0.8125rem;
  color: var(--text-secondary);
  line-height: 1.5;
}

.docs-grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
.docs-grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; }

/* Protocol Actors Diagram */
.actors-diagram {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  margin-top: 16px;
}

.actor-card {
  background: var(--bg-tertiary);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 24px;
  text-align: center;
  position: relative;
}

.actor-card .actor-icon {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 12px;
  font-size: 1.25rem;
}

.actor-card h4 { font-size: 0.9375rem; font-weight: 600; margin-bottom: 4px; }
.actor-card p { font-size: 0.75rem; color: var(--text-muted); }

/* Badge */
.badge {
  display: inline-block;
  font-size: 0.6875rem;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 10px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.badge-coming { background: rgba(240, 136, 62, 0.15); color: var(--accent-orange); }
.badge-new { background: var(--accent-dim); color: var(--accent); }

/* Support */
.support-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
}

.support-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 28px;
  transition: all var(--transition);
}

.support-card:hover { border-color: var(--text-muted); }

.support-card h3 {
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: 8px;
}

.support-card p {
  font-size: 0.8125rem;
  color: var(--text-secondary);
  line-height: 1.6;
}

.contact-banner {
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 40px;
  text-align: center;
  margin-top: 32px;
}

.contact-banner h3 {
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 10px;
}

.contact-banner p {
  color: var(--text-secondary);
  font-size: 0.9375rem;
  margin-bottom: 20px;
}

/* Responsive */
@media (max-width: 1024px) {
  .card-grid-3 { grid-template-columns: repeat(2, 1fr); }
  .community-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-inner { grid-template-columns: repeat(2, 1fr); }
  .actors-diagram { grid-template-columns: repeat(2, 1fr); }
  .docs-main { padding: 32px 24px 64px; }
}

@media (max-width: 768px) {
  .topnav-links { display: none; }
  .topnav-right .search-btn { display: none; }
  .hamburger { display: block; }

  .topnav-links.mobile-open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: 60px;
    left: 0;
    right: 0;
    background: var(--bg-secondary);
    border-bottom: 1px solid var(--border-color);
    padding: 12px;
    gap: 2px;
  }

  .topnav-links.mobile-open a {
    padding: 10px 16px;
    width: 100%;
  }

  .hero { padding: 48px 16px 40px; }
  .hero h1 { font-size: 2rem; }
  .hero p { font-size: 1rem; }
  .hero-ctas { flex-direction: column; align-items: stretch; }

  .section { padding: 40px 16px; }

  .card-grid-3,
  .card-grid-2,
  .launch-grid,
  .docs-grid-2,
  .docs-grid-3,
  .support-grid { grid-template-columns: 1fr; }

  .community-grid { grid-template-columns: 1fr; }
  .footer-inner { grid-template-columns: 1fr 1fr; gap: 24px; }

  .sidebar {
    position: fixed;
    z-index: 90;
    top: 60px;
    left: 0;
    height: calc(100vh - 60px);
    transform: translateX(0);
  }

  .sidebar.collapsed { transform: translateX(-100%); width: var(--sidebar-width); opacity: 1; }

  .sidebar-toggle { position: fixed; top: 72px; }

  .docs-main { padding: 24px 16px 48px; }
  .docs-main h1 { font-size: 1.75rem; }

  .actors-diagram { grid-template-columns: 1fr 1fr; }

  .cli-header { padding: 24px 20px 16px; }
  .accordion-trigger { padding: 14px 20px; }
  .accordion-content-inner { padding: 0 20px 20px; }
}

@media (max-width: 480px) {
  .footer-inner { grid-template-columns: 1fr; }
  .actors-diagram { grid-template-columns: 1fr; }
}
